import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int num_tests = 1;
        for (int i = 0; i < num_tests; i++) {
            runSimulation(br);
        }
    }

    public static void runSimulation(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        double[] probs = new double[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            probs[i] = Double.parseDouble(st.nextToken());
        }
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (Math.abs(probs[i]) < 1e-6) {
                output.append("0 ");
                continue;
            }
            int m = n - 1;
            int size = 1 << m;
            double[] dp = new double[size];
            Arrays.fill(dp, 0.0);
            List<Double> others = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (j != i) {
                    others.add(probs[j]);
                }
            }
            dp[0] = probs[i];
            double total = dp[0];
            for (int mask = 1; mask < size; mask++) {
                double sumP = 0.0, sumVal = 0.0;
                int cnt = 0;
                for (int t = 0; t < m; t++) {
                    if (((mask >> t) & 1) == 1) {
                        sumP += others.get(t);
                        sumVal += others.get(t) * dp[mask ^ (1 << t)];
                        cnt++;
                    }
                }
                double denom = 1 - sumP;
                if (Math.abs(denom) < 1e-12) {
                    dp[mask] = 0.0;
                } else {
                    dp[mask] = sumVal / denom;
                }
                if (cnt < k) {
                    total += dp[mask];
                }
            }
            output.append(total).append(" ");
        }
        System.out.println(output.toString().trim());
    }
}
